const item = $input.first().json;
const cfg = {
  seoQueueSheetId: item.seoQueueSheetId,
  seoLogSheetId: item.seoLogSheetId,
  seoQueueSheetName: item.seoQueueSheetName,
  seoLogSheetName: item.seoLogSheetName,
  workflowVersion: item.workflowVersion,
  slackChannel: item.slackChannel
};
const execution = item.execution || {};
const workflow = item.workflow || {};
return {
  json: {
    documentId: execution.data?.[0]?.json?.documentId || execution.data?.[0]?.json?.['Document ID'] || 'unknown',
    workflowName: workflow.name,
    workflowId: workflow.id,
    errorMessage: execution.error?.message || item.message || 'Unknown error',
    errorStack: execution.error?.stack || '',
    lastNode: execution.lastNodeExecuted,
    timestamp: new Date().toISOString(),
    status: 'Failed',
    version: cfg.workflowVersion || '1.0.0',
    _config: cfg
  }
};

const input = $('SEO - Lexical Extract').first().json;
const gsc = $('Google Search Console').first().json;
const rows = gsc?.rows || [];
let impressions = 0, clicks = 0, ctr = 0, position = 0;
const queries = [];
for (const r of rows) {
  impressions += r.impressions || 0;
  clicks += r.clicks || 0;
  position += r.position || 0;
  if (r.keys?.[0]) queries.push({ query: r.keys[0], page: r.keys[1], impressions: r.impressions, clicks: r.clicks, ctr: r.ctr, position: r.position });
}
if (rows.length) { ctr = clicks / impressions; position = position / rows.length; }
const topQueries = queries.sort((a,b) => (b.impressions||0)-(a.impressions||0)).slice(0, 10);
return {
  json: {
    ...input,
    gsc: { impressions, clicks, ctr: Math.round(ctr * 10000)/100, avgPosition: Math.round(position * 10)/10, topQueries },
    auditComplete: true
  }
};

const base = $('SEO - Lexical Extract').first().json;
const content = $input.first().json.message?.content || '{}';
let meta = {};
try { const m = content.match(/\{[\s\S]*\}/); meta = m ? JSON.parse(m[0]) : {}; } catch(e) {}
const site = (base._config || {}).payloadSiteUrl || '';
if (!meta.canonicalUrl) meta.canonicalUrl = `${site}/${base.slug}`;
if (!meta.seoSlug) meta.seoSlug = base.slug;
const readingTime = Math.max(1, Math.ceil((base.wordCount || 0) / 200));
return { json: { ...base, ...meta, estimatedReadingTime: readingTime } };

const base = $('SEO - Lexical Extract').first().json;
const content = $input.first().json.message?.content || '{}';
let schema = null;
try {
  const m = content.match(/\{[\s\S]*\}/);
  schema = m ? JSON.parse(m[0]) : null;
} catch(e) { schema = null; }
if (!schema) {
  schema = {
    '@context': 'https://schema.org',
    '@graph': [{
      '@type': 'Article',
      headline: base.metaTitle || base.title,
      description: base.metaDescription || base.excerpt,
      url: base.canonicalUrl
    }]
  };
}
return { json: { ...base, schema, jsonLd: JSON.stringify(schema) } };

// Markdown → Lexical — see code/markdown-to-lexical.js
const input = $input.first().json;
const markdown = input.optimizedContent || input.markdown || '';
const LEXICAL_VERSION = 1;
function makeText(text) { return { type: 'text', detail: 0, format: 0, mode: 'normal', style: '', text, version: LEXICAL_VERSION }; }
function makeParagraph(text) { return { type: 'paragraph', format: '', indent: 0, version: LEXICAL_VERSION, direction: 'ltr', children: text ? [makeText(text)] : [] }; }
function makeHeading(level, text) { return { type: 'heading', tag: `h${level}`, format: '', indent: 0, version: LEXICAL_VERSION, direction: 'ltr', children: [makeText(text)] }; }
function parseList(lines, ordered) {
  return { type: 'list', format: '', indent: 0, version: LEXICAL_VERSION, direction: 'ltr', listType: ordered ? 'number' : 'bullet', start: 1, tag: ordered ? 'ol' : 'ul',
    children: lines.map(line => ({ type: 'listitem', format: '', indent: 0, version: LEXICAL_VERSION, direction: 'ltr', value: 1,
      children: [makeParagraph(line.replace(/^(\d+\.\s+|-\s+)/, ''))] })) };
}
function markdownToLexical(md) {
  const lines = md.replace(/\r\n/g, '\n').split('\n');
  const children = []; let i = 0;
  while (i < lines.length) {
    const t = lines[i].trim(); if (!t) { i++; continue; }
    const hm = t.match(/^(#{1,6})\s+(.+)$/);
    if (hm) { children.push(makeHeading(hm[1].length, hm[2])); i++; continue; }
    if (/^-\s+/.test(t)) { const ls = []; while (i < lines.length && /^-\s+/.test(lines[i].trim())) { ls.push(lines[i].trim()); i++; } children.push(parseList(ls, false)); continue; }
    const pl = []; while (i < lines.length && lines[i].trim() && !lines[i].trim().match(/^#{1,6}\s/) && !/^-\s+/.test(lines[i].trim())) { pl.push(lines[i].trim()); i++; }
    children.push(makeParagraph(pl.join(' ')));
  }
  return { root: { type: 'root', format: '', indent: 0, version: LEXICAL_VERSION, direction: 'ltr', children } };
}
const body = input.body?.root ? input.body : markdownToLexical(markdown);
const patch = {
  title: input.title,
  excerpt: input.excerpt || input.metaDescription?.slice(0, 200),
  body,
  estimatedReadingTime: input.estimatedReadingTime,
  lastUpdated: new Date().toISOString(),
  seo: {
    metaTitle: input.metaTitle,
    metaDescription: input.metaDescription,
    searchKeywords: input.searchKeywords || [],
    noIndex: false,
    noFollow: false
  },
  ai: {
    aiTags: input.aiTags || [],
    featureKeywords: input.featureKeywords || [],
    businessKeywords: input.businessKeywords || [],
    gisKeywords: input.gisKeywords || [],
    crmKeywords: input.crmKeywords || [],
    locationIntelligenceKeywords: input.locationIntelligenceKeywords || [],
    promptKeywords: input.promptKeywords || [],
    score: input.seoScore
  }
};
if (input.tags?.length) patch.tags = input.tags;
if (input.relatedFeatures?.length) patch.relatedFeatures = input.relatedFeatures;
return { json: { ...input, patchPayload: patch, documentId: input.documentId || input.id } };

const req = $('Build PATCH Payload').first().json;
const resp = $input.first().json;
return { json: { ...req, payloadUpdated: true, payloadResponse: resp, updatedAt: new Date().toISOString() } };

const row = $input.first().json;
const cfg = row._config || {};
return { json: { ...row, startTime: new Date().toISOString(), startMs: Date.now(), workflowVersion: cfg.workflowVersion || '1.0.0', documentId: row['Document ID'] || row.documentId, apiUrl: row['API URL'] || row.apiUrl, slug: row.Slug || row.slug, title: row.Title || row.title, category: row.Category || row.category, _config: cfg } };

const init = $('Initialize Run').first().json;
const doc = $input.first().json;
return { json: { ...init, ...doc, oldScore: doc.ai?.score ?? null, seo: doc.seo || {}, excerpt: doc.excerpt || '' } };

const lexical = $('Extract Lexical Content').first().json;
const kw = $('Keyword Research').first().json;
const comp = $('Competitor Analysis').first().json;
return { json: { ...lexical, ...kw, ...comp } };

const ai = $('AI Optimization').first().json;
const meta = $('Metadata Generation').first().json;
const schema = $('Schema Generation').first().json;
return { json: { ...ai, ...meta, ...schema } };

// Content validation — see code/content-validator.js
const data = $input.first().json;
const content = data.optimizedContent || '';
const errors = [];
const warnings = [];
if (!content.trim()) errors.push('Empty content');
if (!/##\s*FAQ/i.test(content)) errors.push('Missing FAQ section');
if (!data.metaTitle) errors.push('Missing meta title');
if (!data.metaDescription) errors.push('Missing meta description');
if (/lorem ipsum|placeholder|\[insert/i.test(content)) errors.push('Placeholder content detected');
const passed = errors.length === 0;
return { json: { ...data, validation: { passed, errors, warnings, status: !passed ? 'Failed' : warnings.length > 2 ? 'Needs Review' : 'Completed' }, validationPassed: passed, finalStatus: !passed ? 'Failed' : warnings.length > 2 ? 'Needs Review' : 'Completed' } };

// SEO Score — see code/seo-score-calculator.js
const data = $input.first().json;
const weights = { contentQuality: 0.2, keywordUsage: 0.15, headingStructure: 0.15, metadata: 0.15, readability: 0.1, semanticCoverage: 0.1, internalLinking: 0.05, faq: 0.05, schema: 0.05 };
const wc = data.wordCount || 0;
const components = {
  contentQuality: wc >= 1200 ? 100 : wc >= 800 ? 80 : 60,
  keywordUsage: 75,
  headingStructure: (data.headings?.length >= 3) ? 85 : 50,
  metadata: (data.metaTitle && data.metaDescription) ? 80 : 30,
  readability: 75,
  semanticCoverage: (data.lsiKeywords?.length >= 5) ? 80 : 40,
  internalLinking: (/\]\(\//.test(data.optimizedContent || '') ? 80 : 30),
  faq: (/##\s*FAQ/i.test(data.optimizedContent || '') ? 90 : 0),
  schema: data.schema ? 100 : 0
};
let total = 0; for (const [k,w] of Object.entries(weights)) total += (components[k]||0)*w;
const seoScore = Math.round(total);
return { json: { ...data, seoScore, scoreComponents: components, scoreDelta: data.oldScore != null ? seoScore - data.oldScore : null } };

const init = $('Initialize Run').first().json;
const data = $input.first().json;
const endMs = Date.now();
return { json: { ...data, endTime: new Date().toISOString(), durationMs: endMs - init.startMs, rowDocumentId: init.documentId } };

const d = $input.first().json;
const cfg = d._config || {};
const minWords = parseInt(cfg.minWordCount || 1200);
const catalog = (cfg.internalLinkCatalog || 'crm-mapping,heat-maps,territories').split(',');
const prompt = `Optimize this documentation for SEO.

Title: ${d.title}
Slug: ${d.slug}
Category: ${d.category}
Excerpt: ${d.excerpt}
Word count: ${d.wordCount} (target: ${minWords}+)
Intent: ${d.searchIntent}
Primary: ${d.primaryKeyword}
Secondary: ${(d.secondaryKeywords || []).join(', ')}
LSI: ${(d.lsiKeywords || []).slice(0, 10).join(', ')}
PAA: ${(d.peopleAlsoAsk || []).slice(0, 5).join('; ')}
Competitors: ${(d.competitorUrls || []).map(c => c.title).join(', ')}
Missing topics: ${(d.missingTopics || []).join(', ')}
Internal links catalog: ${catalog.join(', ')}

Metadata: ${JSON.stringify(d.seo || {})}

Content:
${d.markdown}

Requirements: H1-H4 hierarchy, grade 7-9 readability, EEAT, FAQ 5+, conclusion, 3-5 internal links [/text](/slug), no filler, no hallucinations. Return ONLY markdown.`;
return { json: { ...d, aiPrompt: prompt, minWordCount: minWords } };

const base = $('Build AI Prompt').first().json;
const resp = $input.first().json;
const content = resp.message?.content || resp.text || '';
const optimized = content.replace(/^```markdown\n?/i, '').replace(/\n?```$/i, '').trim();
const wordCount = optimized.split(/\s+/).filter(Boolean).length;
const tokensUsed = resp.usage?.total_tokens || resp.tokenUsage?.totalTokens || null;
return {
  json: {
    ...base,
    optimizedContent: optimized,
    wordCount,
    tokensUsed,
    contentExpanded: wordCount >= (base.minWordCount || 1200)
  }
};
